-- 幂等：先按 rule_code 清理再插入，可重复执行；id 由雪花算法生成（重跑会变化，幂等靠 rule_code 清理保证）。
-- enable_status=0（1 生效 / 0 未启用，可用脚本参数调整；含待校准参数默认 0，见 README）。
-- 前置：先执行同目录 _scan_rule_indexes.sql 补扫描腿索引，否则本种子一上量就是 il_eco / il_order_bol / il_order_container 逐行全表扫。
-- app_id/tenant_code 等归属列未写死，按环境需要自行 UPDATE。
-- =============================================================================
SET NAMES utf8mb4;

-- 幂等清理（含历史逻辑删除行，避免 uk_exc_rule_code 冲突）
DELETE FROM `platform_exception_rule` WHERE `rule_code` IN (
  'EXC-BL-015', 'EXC-BL-016', 'EXC-CUS-001', 'EXC-FIN-018',
  'EXC-ODR-001', 'EXC-ODR-018', 'EXC-ODR-019', 'EXC-ODR-020'
);

INSERT INTO `platform_exception_rule`
  (`id`, `rule_code`, `rule_name`, `domain_code`, `rule_desc`, `level`, `rule_kind`, `escalation_of_rule_code`, `trigger_type`, `cron_expression`, `listen_entities`, `pipeline_json`, `threshold_json`, `owner_selector`, `resolve_policy`, `storm_json`, `biz_type`, `mutual_exclusive_group`, `flow_template`, `biz_url_template`, `enable_status`, `engine_version`, `version`, `seq_no`, `scan_status`, `del_status`, `create_at`, `update_at`, `creator`, `creator_name`) VALUES
('376214032761360384', 'EXC-BL-015', '未收款放单', 'BL', '提单已放单但该订单应收仍未核销，催操作与业务跟款。详细口径、取数面与责任人见同目录 README.md。', 'P0', 'ALERT', NULL, 'SCAN', '0 0 * * * ?', NULL, '{"steps":[{"name":"judge","lang":"js","content":"const rows = $gl.sql.query(`\\n  SELECT ''ORDER'' AS biz_type,\\n         b.order_id AS biz_id, e.eco_no AS biz_label,\\n         e.customer_id, e.customer_name,\\n         e.operator_id, e.operator_name, e.salesman_id,\\n         COALESCE(g.grant_time, b.update_at) AS grant_time,\\n         DATEDIFF(NOW(), COALESCE(g.grant_time, b.update_at)) AS days_since_grant\\n  FROM il_order_bol b\\n  JOIN il_eco e ON e.id = b.order_id AND e.del_status = 0\\n  LEFT JOIN (\\n    SELECT order_id, MAX(biz_status_time) AS grant_time\\n    FROM il_order_bol_grant\\n    WHERE del_status = 0\\n    GROUP BY order_id\\n  ) g ON g.order_id = b.order_id\\n  WHERE b.del_status = 0\\n    AND b.bol_status IN (''2'',''3'',''4'')\\n    AND DATEDIFF(NOW(), COALESCE(g.grant_time, b.update_at)) >= :daysAfer\\n    AND COALESCE(g.grant_time, b.update_at) >= DATE_SUB(NOW(), INTERVAL :lookbackDays DAY)\\n    AND EXISTS (\\n      SELECT 1 FROM il_so_container_fee_detail f\\n      WHERE f.order_id = b.order_id AND f.del_status = 0\\n        AND f.fee_type = ''1'' AND f.amount_not_written_off > 0\\n    )\\n`, $params)\\nreturn rows.map(r => ({\\n  bizType: r.biz_type,\\n  bizId: r.biz_id,\\n  bizLabel: r.biz_label,\\n  operatorId: r.operator_id,\\n  salesmanId: r.salesman_id,\\n  title: `订单 ${r.biz_label}（${r.customer_name}）已放单 ${r.days_since_grant} 天，应收仍未核销`,\\n  anchorTime: r.grant_time,\\n  snapshot: {\\n    ecoNo: r.biz_label,\\n    customer: { id: r.customer_id, name: r.customer_name },\\n    operatorName: r.operator_name,\\n    salesmanId: r.salesman_id,\\n    grantTime: r.grant_time,\\n    daysSinceGrant: r.days_since_grant\\n  }\\n}))"}]}', '{"daysAfer":7,"lookbackDays":90}', '{"handlers":[{"type":"BIZ_FIELD","fields":["operatorId","salesmanId"]}],"cc":[]}', 'ANY', '{"hitLimit":200,"overflowPolicy":"AGGREGATE","cooldownMinutes":30}', 'ORDER', NULL, 'INTERCEPT', '/fms/so/{bizId}', 0, 'v1', 1, 1, 0, 0, NOW(), NOW(), 'system', '系统初始化'),
('376214032773943296', 'EXC-BL-016', '逾期放单', 'BL', '订单已到或临近 ETA 仍未申请放单，催操作及时发起放单。详细口径、取数面与责任人见同目录 README.md。', 'P2', 'ALERT', NULL, 'SCAN', '0 0 * * * ?', NULL, '{"steps":[{"name":"judge","lang":"js","content":"const rows = $gl.sql.query(`\\n  SELECT ''ORDER'' AS biz_type,\\n         e.id AS biz_id, e.eco_no AS biz_label,\\n         e.customer_id, e.customer_name,\\n         e.operator_id, e.operator_name, e.salesman_id,\\n         e.eta AS anchor_time,\\n         DATEDIFF(e.eta, NOW()) AS lead_days\\n  FROM il_eco e\\n  WHERE e.del_status = 0\\n    AND e.eta IS NOT NULL\\n    AND e.eta <= DATE_ADD(NOW(), INTERVAL :leadDays DAY)\\n    AND e.eta >= DATE_SUB(NOW(), INTERVAL :lookbackDays DAY)\\n    AND e.order_status NOT IN (''0'',''1'',''15'')\\n    AND NOT EXISTS (\\n      SELECT 1 FROM il_order_bol b\\n      WHERE b.order_id = e.id AND b.del_status = 0\\n        AND b.bol_status IN (''1'',''2'',''3'',''4'')\\n    )\\n`, $params)\\nreturn rows.map(r => ({\\n  bizType: r.biz_type,\\n  bizId: r.biz_id,\\n  bizLabel: r.biz_label,\\n  operatorId: r.operator_id,\\n  salesmanId: r.salesman_id,\\n  // lead_days = DATEDIFF(eta, NOW())：ETA 未到为正（前 X 天），已过为负（已逾期 X 天）\\n  title: r.lead_days >= 0\\n    ? `订单 ${r.biz_label}（${r.customer_name}）ETA 前 ${r.lead_days} 天仍未申请放单`\\n    : `订单 ${r.biz_label}（${r.customer_name}）ETA 已逾期 ${-r.lead_days} 天仍未申请放单`,\\n  anchorTime: r.anchor_time,\\n  snapshot: {\\n    ecoNo: r.biz_label,\\n    customer: { id: r.customer_id, name: r.customer_name },\\n    operatorName: r.operator_name,\\n    salesmanId: r.salesman_id,\\n    eta: r.anchor_time,\\n    leadDays: r.lead_days\\n  }\\n}))"}]}', '{"leadDays":7,"lookbackDays":90}', '{"handlers":[{"type":"BIZ_FIELD","fields":["operatorId","salesmanId"]}],"cc":[]}', 'ANY', '{"hitLimit":200,"overflowPolicy":"AGGREGATE","cooldownMinutes":30}', 'ORDER', NULL, 'STANDARD', '/fms/so/{bizId}', 0, 'v1', 1, 2, 0, 0, NOW(), NOW(), 'system', '系统初始化'),
('376214032786526208', 'EXC-CUS-001', '客户超授信', 'CUS', '月结客户名下已受理订单的应收未核销总额超过授信额度，催归属业务与客户对账。详细口径、取数面与责任人见同目录 README.md。', 'P1', 'ALERT', NULL, 'SCAN', '0 30 * * * ?', NULL, '{"steps":[{"name":"judge","lang":"js","content":"const rows = $gl.sql.query(`\\n  SELECT ''CUSTOMER'' AS biz_type,\\n         co.id AS biz_id, co.name AS biz_label,\\n         co.id AS customer_id, co.name AS customer_name,\\n         co.salesman_id, co.salesman_name,\\n         co.line_of_credit AS line_of_credit,\\n         agg.outstanding AS outstanding\\n  FROM (\\n    SELECT e.customer_id, SUM(f.amount_not_written_off) AS outstanding\\n    FROM il_so_container_fee_detail f\\n    JOIN il_eco e ON e.id = f.order_id\\n      AND e.del_status = 0 AND e.order_status NOT IN (''0'',''1'',''15'')\\n    WHERE f.del_status = 0 AND f.fee_type = ''1'' AND f.amount_not_written_off > 0\\n    GROUP BY e.customer_id\\n  ) agg\\n  JOIN il_cooperating_org co ON co.id = agg.customer_id AND co.del_status = 0\\n  WHERE co.settlement_method = ''1''\\n    AND co.line_of_credit IS NOT NULL AND co.line_of_credit > 0\\n    AND agg.outstanding > co.line_of_credit * :utilizationPct / 100\\n`, $params)\\nreturn rows.map(r => ({\\n  bizType: r.biz_type,\\n  bizId: r.biz_id,\\n  bizLabel: r.biz_label,\\n  salesmanId: r.salesman_id,\\n  title: `月结客户 ${r.customer_name} 未核销 ${r.outstanding} 超授信额度 ${r.line_of_credit}`,\\n  snapshot: {\\n    customer: { id: r.customer_id, name: r.customer_name },\\n    salesman: { id: r.salesman_id, name: r.salesman_name },\\n    lineOfCredit: r.line_of_credit,\\n    outstanding: r.outstanding\\n  }\\n}))"}]}', '{"utilizationPct":100}', '{"handlers":[{"type":"BIZ_FIELD","fields":["salesmanId"]}],"cc":[]}', 'ANY', '{"hitLimit":200,"overflowPolicy":"AGGREGATE","cooldownMinutes":30}', 'CUSTOMER', NULL, 'STANDARD', '/fms/customer/{bizId}', 0, 'v1', 1, 3, 0, 0, NOW(), NOW(), 'system', '系统初始化'),
('376214032799109120', 'EXC-FIN-018', '进口订单结算逾期', 'FIN', '进口订单临近 ETA 仍有外部公司（非海桥内部）的应收未核销费用，催操作与业务跟进结算。详细口径、取数面与责任人见同目录 README.md。', 'P1', 'ALERT', NULL, 'SCAN', '0 0 * * * ?', NULL, '{"steps":[{"name":"judge","lang":"js","content":"const rows = $gl.sql.query(`\\n  SELECT ''ORDER'' AS biz_type,\\n         e.id AS biz_id, e.eco_no AS biz_label,\\n         e.customer_id, e.customer_name,\\n         e.operator_id, e.operator_name, e.salesman_id,\\n         e.eta AS anchor_time,\\n         DATEDIFF(e.eta, NOW()) AS lead_days\\n  FROM il_eco e\\n  WHERE e.del_status = 0\\n    AND e.inter_import = 1\\n    AND e.eta IS NOT NULL\\n    AND e.eta <= DATE_ADD(NOW(), INTERVAL :leadDays DAY)\\n    AND e.eta >= DATE_SUB(NOW(), INTERVAL :lookbackDays DAY)\\n    AND EXISTS (\\n      SELECT 1 FROM il_so_container_fee_detail f\\n      WHERE f.order_id = e.id AND f.del_status = 0\\n        AND f.fee_type = ''1'' AND f.amount_not_written_off > 0\\n        AND f.settlement_unit_id IS NOT NULL\\n        AND f.settlement_unit_id NOT IN (:internalUnitIds)\\n    )\\n`, $params)\\nreturn rows.map(r => ({\\n  bizType: r.biz_type,\\n  bizId: r.biz_id,\\n  bizLabel: r.biz_label,\\n  operatorId: r.operator_id,\\n  salesmanId: r.salesman_id,\\n  // lead_days = DATEDIFF(eta, NOW())：ETA 未到为正（前 X 天），已过为负（已逾期 X 天）\\n  title: r.lead_days >= 0\\n    ? `订单 ${r.biz_label}（${r.customer_name}）进口 ETA 前 ${r.lead_days} 天，非海桥结算单位仍有未核销`\\n    : `订单 ${r.biz_label}（${r.customer_name}）进口 ETA 已逾期 ${-r.lead_days} 天，非海桥结算单位仍有未核销`,\\n  anchorTime: r.anchor_time,\\n  snapshot: {\\n    ecoNo: r.biz_label,\\n    customer: { id: r.customer_id, name: r.customer_name },\\n    operatorName: r.operator_name,\\n    salesmanId: r.salesman_id,\\n    eta: r.anchor_time,\\n    leadDays: r.lead_days\\n  }\\n}))"}]}', '{"leadDays":5,"lookbackDays":90,"internalUnitIds":["__REPLACE_WITH_HQ_INTERNAL_UNIT_IDS__"]}', '{"handlers":[{"type":"BIZ_FIELD","fields":["operatorId","salesmanId"]}],"cc":[]}', 'ANY', '{"hitLimit":200,"overflowPolicy":"AGGREGATE","cooldownMinutes":30}', 'ORDER', NULL, 'STANDARD', '/fms/so/{bizId}', 0, 'v1', 1, 4, 0, 0, NOW(), NOW(), 'system', '系统初始化'),
('376214032811692032', 'EXC-ODR-001', '委托受理滞留', 'ODR', '委托单产生后长时间仍未受理，催操作与业务尽快受理。详细口径、取数面与责任人见同目录 README.md。', 'P1', 'ALERT', NULL, 'SCAN', '0 0 * * * ?', NULL, '{"steps":[{"name":"judge","lang":"js","content":"const rows = $gl.sql.query(`\\n  SELECT ''ORDER'' AS biz_type,\\n         e.id AS biz_id, e.eco_no AS biz_label,\\n         e.customer_id, e.customer_name,\\n         e.operator_id, e.operator_name, e.salesman_id,\\n         e.etd AS anchor_time,\\n         DATEDIFF(NOW(), e.etd) AS anchor_elapsed_days\\n  FROM il_eco e\\n  WHERE e.del_status = 0\\n    AND e.etd IS NOT NULL\\n    AND e.etd <= DATE_SUB(NOW(), INTERVAL :staleDays DAY)\\n    AND e.etd >= DATE_SUB(NOW(), INTERVAL :lookbackDays DAY)\\n    AND e.order_status IN (''0'',''1'')\\n`, $params)\\nreturn rows.map(r => ({\\n  bizType: r.biz_type,\\n  bizId: r.biz_id,\\n  bizLabel: r.biz_label,\\n  operatorId: r.operator_id,\\n  salesmanId: r.salesman_id,\\n  title: `订单 ${r.biz_label}（${r.customer_name}）ETD 已过 ${r.anchor_elapsed_days} 天仍未受理`,\\n  anchorTime: r.anchor_time,\\n  snapshot: {\\n    ecoNo: r.biz_label,\\n    customer: { id: r.customer_id, name: r.customer_name },\\n    operatorName: r.operator_name,\\n    salesmanId: r.salesman_id,\\n    etd: r.anchor_time,\\n    elapsedDays: r.anchor_elapsed_days\\n  }\\n}))"}]}', '{"staleDays":7,"lookbackDays":90}', '{"handlers":[{"type":"BIZ_FIELD","fields":["operatorId","salesmanId"]}],"cc":[]}', 'ANY', '{"hitLimit":200,"overflowPolicy":"AGGREGATE","cooldownMinutes":30}', 'ORDER', NULL, 'STANDARD', '/fms/so/{bizId}', 0, 'v1', 1, 5, 0, 0, NOW(), NOW(), 'system', '系统初始化'),
('376214032824274944', 'EXC-ODR-018', '截关前未进港', 'ODR', '距截关不足 6 小时而柜子仍未进港，催操作跟进疏港或改配。详细口径、取数面与责任人见同目录 README.md。', 'P0', 'ALERT', NULL, 'SCAN', '0 0/15 * * * ?', NULL, '{"steps":[{"name":"judge","lang":"js","content":"const rows = $gl.sql.query(`\\n  SELECT ''ORDER'' AS biz_type,\\n         e.id AS biz_id, e.eco_no AS biz_label,\\n         e.customer_id, e.customer_name,\\n         e.operator_id, e.operator_name, e.salesman_id,\\n         e.cut_off_slip AS cut_off_time,\\n         TIMESTAMPDIFF(HOUR, NOW(), e.cut_off_slip) AS hours_to_cut,\\n         e.cut_off_slip AS anchor_time\\n  FROM il_eco e\\n  LEFT JOIN ob_portal.ot_container_status cs\\n    ON cs.bill_no = e.mbl_no AND cs.container_no = e.container_no AND cs.del_status = 0\\n  WHERE e.del_status = 0\\n    AND e.cut_off_slip IS NOT NULL\\n    AND e.container_no IS NOT NULL AND e.container_no <> ''''\\n    AND e.cut_off_slip <= DATE_ADD(NOW(), INTERVAL :leadHours HOUR)\\n    AND e.cut_off_slip >= DATE_SUB(NOW(), INTERVAL :lookbackDays DAY)\\n    AND cs.gitm_time IS NULL\\n`, $params)\\nreturn rows.map(r => ({\\n  bizType: r.biz_type,\\n  bizId: r.biz_id,\\n  bizLabel: r.biz_label,\\n  operatorId: r.operator_id,\\n  salesmanId: r.salesman_id,\\n  // hours_to_cut = TIMESTAMPDIFF(HOUR, NOW(), cut_off)：截关未到为正，已过为负（回看窗口内会命中）\\n  title: r.hours_to_cut >= 0\\n    ? `订单 ${r.biz_label}（${r.customer_name}）截关前 ${r.hours_to_cut} 小时仍未进港`\\n    : `订单 ${r.biz_label}（${r.customer_name}）截关已逾 ${-r.hours_to_cut} 小时仍未进港`,\\n  anchorTime: r.anchor_time,\\n  snapshot: {\\n    ecoNo: r.biz_label,\\n    customer: { id: r.customer_id, name: r.customer_name },\\n    operatorName: r.operator_name,\\n    salesmanId: r.salesman_id,\\n    cutOffTime: r.cut_off_time,\\n    hoursToCut: r.hours_to_cut\\n  }\\n}))"}]}', '{"leadHours":6,"lookbackDays":2}', '{"handlers":[{"type":"BIZ_FIELD","fields":["operatorId","salesmanId"]}],"cc":[]}', 'ANY', '{"hitLimit":200,"overflowPolicy":"AGGREGATE","cooldownMinutes":30}', 'ORDER', 'ODR_002_017', 'STANDARD', '/fms/so/{bizId}', 0, 'v1', 1, 6, 0, 0, NOW(), NOW(), 'system', '系统初始化'),
('376214032836857856', 'EXC-ODR-019', '到港超期未提柜', 'ODR', '订单到港超 pickupDays（默认 2 天）仍未提柜（排除 SOC 自备箱），催操作与业务及时提柜。详细口径、取数面与责任人见同目录 README.md。', 'P2', 'ALERT', NULL, 'SCAN', '0 0 * * * ?', NULL, '{"steps":[{"name":"judge","lang":"js","content":"const rows = $gl.sql.query(`\\n  SELECT ''ORDER'' AS biz_type,\\n         e.id AS biz_id, e.eco_no AS biz_label,\\n         e.customer_id, e.customer_name,\\n         e.operator_id, e.operator_name, e.salesman_id,\\n         MIN(COALESCE(cs.pdba_time, cs.bdar_time)) AS arrive_time,\\n         TIMESTAMPDIFF(DAY, MIN(COALESCE(cs.pdba_time, cs.bdar_time)), NOW()) AS elapsed_days,\\n         GROUP_CONCAT(DISTINCT cs.container_no ORDER BY cs.container_no SEPARATOR '','') AS container_nos\\n  FROM il_eco e\\n  JOIN ob_portal.ot_container_status cs\\n    ON cs.bill_no = e.mbl_no AND cs.container_no = e.container_no AND cs.del_status = 0\\n  WHERE e.del_status = 0\\n    AND e.biz_type < ''5''\\n    AND (e.order_status IS NULL OR e.order_status NOT IN (''0'', ''1'', ''15''))\\n    AND e.container_no IS NOT NULL AND e.container_no <> ''''\\n    AND NOT EXISTS (\\n          SELECT 1 FROM il_order_container oc\\n          WHERE oc.order_id = e.id AND oc.container_no = e.container_no\\n            AND oc.del_status = 0\\n            AND UPPER(TRIM(oc.container_ownership_type)) = ''SOC''\\n        )\\n    AND cs.stcs_time IS NULL\\n    AND COALESCE(cs.pdba_time, cs.bdar_time) < DATE_SUB(NOW(), INTERVAL :pickupDays DAY)\\n    AND COALESCE(cs.pdba_time, cs.bdar_time) >= DATE_SUB(NOW(), INTERVAL :lookbackDays DAY)\\n  GROUP BY e.id, e.eco_no, e.customer_id, e.customer_name,\\n           e.operator_id, e.operator_name, e.salesman_id\\n`, $params)\\nreturn rows.map(r => {\\n  // elapsed_days = 抵港至今整天数（锚点恒在过去，不会为负）；超出 pickupDays 的部分即逾期天数\\n  const overdueDays = Math.max(r.elapsed_days - $params.pickupDays, 1)\\n  return {\\n    bizType: r.biz_type,\\n    bizId: r.biz_id,\\n    bizLabel: r.biz_label,\\n    operatorId: r.operator_id,\\n    salesmanId: r.salesman_id,\\n    title: `订单 ${r.biz_label}（${r.customer_name}）到港超 ${$params.pickupDays} 天仍未提柜，已逾期 ${overdueDays} 天`,\\n    anchorTime: r.arrive_time,\\n    snapshot: {\\n      ecoNo: r.biz_label,\\n      customer: { id: r.customer_id, name: r.customer_name },\\n      operatorName: r.operator_name,\\n      salesmanId: r.salesman_id,\\n      arriveTime: r.arrive_time,\\n      elapsedDays: r.elapsed_days,\\n      overdueDays: overdueDays,\\n      containerNos: r.container_nos\\n    }\\n  }\\n})"}]}', '{"pickupDays":2,"lookbackDays":60}', '{"handlers":[{"type":"BIZ_FIELD","fields":["operatorId","salesmanId"]}],"cc":[]}', 'ANY', '{"hitLimit":200,"overflowPolicy":"AGGREGATE","cooldownMinutes":30}', 'ORDER', 'ODR_003_019', 'STANDARD', '/fms/so/{bizId}', 0, 'v1', 1, 7, 0, 0, NOW(), NOW(), 'system', '系统初始化'),
('376214032849440768', 'EXC-ODR-020', '提柜超期未还箱', 'ODR', '订单提柜超 returnDays（默认 4 天）仍未还箱（排除 SOC 自备箱），催操作与业务及时还箱避开滞箱费。详细口径、取数面与责任人见同目录 README.md。', 'P1', 'ALERT', NULL, 'SCAN', '0 0 * * * ?', NULL, '{"steps":[{"name":"judge","lang":"js","content":"const rows = $gl.sql.query(`\\n  SELECT ''ORDER'' AS biz_type,\\n         e.id AS biz_id, e.eco_no AS biz_label,\\n         e.customer_id, e.customer_name,\\n         e.operator_id, e.operator_name, e.salesman_id,\\n         e.last_free_day,\\n         MIN(cs.stcs_time) AS pick_up_time,\\n         TIMESTAMPDIFF(DAY, MIN(cs.stcs_time), NOW()) AS elapsed_days,\\n         GROUP_CONCAT(DISTINCT cs.container_no ORDER BY cs.container_no SEPARATOR '','') AS container_nos\\n  FROM il_eco e\\n  JOIN ob_portal.ot_container_status cs\\n    ON cs.bill_no = e.mbl_no AND cs.container_no = e.container_no AND cs.del_status = 0\\n  WHERE e.del_status = 0\\n    AND e.biz_type < ''5''\\n    AND (e.order_status IS NULL OR e.order_status NOT IN (''0'', ''1'', ''15''))\\n    AND e.container_no IS NOT NULL AND e.container_no <> ''''\\n    AND NOT EXISTS (\\n          SELECT 1 FROM il_order_container oc\\n          WHERE oc.order_id = e.id AND oc.container_no = e.container_no\\n            AND oc.del_status = 0\\n            AND UPPER(TRIM(oc.container_ownership_type)) = ''SOC''\\n        )\\n    AND cs.rcve_time IS NULL\\n    AND cs.stcs_time < DATE_SUB(NOW(), INTERVAL :returnDays DAY)\\n    AND cs.stcs_time >= DATE_SUB(NOW(), INTERVAL :lookbackDays DAY)\\n  GROUP BY e.id, e.eco_no, e.customer_id, e.customer_name,\\n           e.operator_id, e.operator_name, e.salesman_id, e.last_free_day\\n`, $params)\\nreturn rows.map(r => {\\n  // elapsed_days = 提柜至今整天数（锚点恒在过去，不会为负）；超出 returnDays 的部分即逾期天数\\n  const overdueDays = Math.max(r.elapsed_days - $params.returnDays, 1)\\n  return {\\n    bizType: r.biz_type,\\n    bizId: r.biz_id,\\n    bizLabel: r.biz_label,\\n    operatorId: r.operator_id,\\n    salesmanId: r.salesman_id,\\n    title: `订单 ${r.biz_label}（${r.customer_name}）提柜超 ${$params.returnDays} 天仍未还箱，已逾期 ${overdueDays} 天`,\\n    anchorTime: r.pick_up_time,\\n    snapshot: {\\n      ecoNo: r.biz_label,\\n      customer: { id: r.customer_id, name: r.customer_name },\\n      operatorName: r.operator_name,\\n      salesmanId: r.salesman_id,\\n      pickUpTime: r.pick_up_time,\\n      lastFreeDay: r.last_free_day,\\n      elapsedDays: r.elapsed_days,\\n      overdueDays: overdueDays,\\n      containerNos: r.container_nos\\n    }\\n  }\\n})"}]}', '{"returnDays":4,"lookbackDays":60}', '{"handlers":[{"type":"BIZ_FIELD","fields":["operatorId","salesmanId"]}],"cc":[]}', 'ANY', '{"hitLimit":200,"overflowPolicy":"AGGREGATE","cooldownMinutes":30}', 'ORDER', 'ODR_020_TRN_005', 'STANDARD', '/fms/so/{bizId}', 0, 'v1', 1, 8, 0, 0, NOW(), NOW(), 'system', '系统初始化');
